out=[r[:] for r in g]
# connect consecutive foreground 4s in each row/column, fill 9s between
for axis in (0,1):
 for i in range(len(g) if axis==1 else len(g[0])):
  line=[g[i][j] for j in range(19)] if axis==1 else [g[j][i] for j in range(10)]
  inds=[j for j,v in enumerate(line) if v==4]
  for a,b in zip(inds,inds[1:]):
   if all(line[k]==9 for k in range(a+1,b)):
    for k in range(a+1,b):
     if axis==1:out[i][k]=2
     else:out[k][i]=2
print('\n'.join(str(r) for r in out))
